    main_body();
    front_bezel();
    mounting_pins();
  }
  rear_cavity();
  segment_led_windows();
  decimal_point();
  segment_cutouts();
}

// Parameters
mast_height = 150; //[75:300:1]
mast_diameter = 6; //[3:12:0.5]
base_diameter = 30; //[15:60:1]
base_thickness = 6; //[3:12:0.5]
flange_diameter = 40; //[20:80:1]
flange_thickness = 3; //[1.5:8:0.5]
hole_count = 3; //[2:8:1]
