  color("Silver") difference() {
    cylinder(r=outer_diameter_mm/2, h=width_mm, center=true);
    cylinder(r=outer_diameter_mm/2 - ring_radial_thickness_mm, h=width_mm + 2*eps_mm, center=true);
  }
}

