module bearing_ball() {
  color("Copper") {
    for (i = [0:ball_count-1]) {
      rotate([0, 0, i*360/ball_count])
      translate([((bore_diameter_mm/2 + ring_radial_thickness_mm) + (outer_diameter_mm/2 - ring_radial_thickness_mm))/2, 0, 0])
      sphere(r=ball_diameter_mm/2, center=true);
