    z_ap = (thickness_mm/2 + front_face_thickness_mm) - aperture_depth_mm/2 + overlap_mm;
    translate([0, 0, z_ap])
      cube([aperture_width_mm, aperture_height_mm, aperture_depth_mm + 2*overlap_mm], center=true);

