overlap = 0.6;

// ---------------- Helpers ----------------
module rounded_rect_2d(w, h, r) {
    r2 = min(r, min(w, h)/2);
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(w/2 - r2), sy*(h/2 - r2)]) circle(r=r2);
    }
}

module rounded_box(w, h, d, r) {
    linear_extrude(height=d, center=true)
        rounded_rect_2d(w, h, r);
}

// ---------------- Model ----------------
module iec_fused_inlet_old() {

