    fuse_pocket_h = fuse_drawer_height - 2.0;
    fuse_pocket_d = fuse_drawer_depth - 2.0;
    z_fuse_front = z_fuse_center + fuse_drawer_depth/2;
    z_fuse_pocket_center = z_fuse_front - fuse_pocket_d/2 + overlap;

