    term_pocket_w = terminal_block_w - 2.0;
    term_pocket_h = terminal_block_h - 2.0;
    z_term_rear = z_term_center - terminal_block_d/2;
    z_term_pocket_center = z_term_rear + term_pocket_d/2 - overlap;

