module rounded_rect_prism(size=[10,10,2], r=1, center=true) {
  x = size[0]; y = size[1]; z = size[2];
  rr = min(r, x/2, y/2);
  translate(center ? [0,0,0] : [x/2,y/2,z/2])
    linear_extrude(height=z, center=true)
      rounded_rect_2d(x, y, rr);
