usb_w = 14.0;
usb_d = 12.0;

term_h = 10.0;
term_w = 36.0;
term_d = 12.0;

headers_h = 6.0;
headers_w = 50.0;
headers_d = 8.0;

driver_h = 12.0;
driver_w = 18.0;
