overlap = 1.0; //[0.5:2.0:0.1]
edge_chamfer = 1.0; //[0.5:2.5:0.1]
fillet_r = 1.0; //[0.5:3.0:0.1]
groove_r = 2.0; //[1.0:4.0:0.1]
groove_depth = 1.2; //[0.5:3.0:0.1]
groove_z = 4.5; //[2.0:8.0:0.1]
