                cylinder(h=L + overlap_mm, r=sh_r, center=false);

            // Faux thread ridges along shank (visual only)
            translate([0,0,-L])
                faux_threads(L*thread_coverage_ratio, sh_r, thread_radial_amplitude_mm, thread_pitch_mm);

