    chamfer_corner_cut();
    translate([-(plate_length - 2*chamfer_leg)/2, 0, 0]) chamfer_corner_cut();
    translate([-(plate_length - 2*chamfer_leg)/2, -(plate_width - 2*chamfer_leg)/2, 0]) chamfer_corner_cut();
