module sheet_profile_2d(L, W, c) {
    polygon(points=[
        [ L/2 - c,  W/2],
        [-L/2 + c,  W/2],
        [-L/2,      W/2 - c],
        [-L/2,     -W/2 + c],
        [-L/2 + c, -W/2],
