module mount_holes(z_center, h) {
    for (xsgn = [-1, 1])
        for (ysgn = [-1, 1])
            translate([xsgn*mount_hole_spacing/2, ysgn*mount_hole_spacing/2, z_center])
                cylinder(d=mount_hole_diameter, h=h, center=true);
}

